  /// < STT NOT supported
  static const int STT_ERROR_NOT_SUPPORTED = -1073741822;

  /// < Invalid state
  static const int STT_ERROR_INVALID_STATE = -49283071;

  /// < Invalid language
  static const int STT_ERROR_INVALID_LANGUAGE = -49283070;

  /// < No available engine
  static const int STT_ERROR_ENGINE_NOT_FOUND = -49283069;

  /// < Operation failed
