  /// < Not supported feature of current engine
  static const int STT_ERROR_NOT_SUPPORTED_FEATURE = -49283067;

  /// < Recording timed out @if MOBILE (Since 3.0) @elseif WEARABLE (Since 2.3.2) @endif
